import{_ as a,o as E,c as s,ai as e}from"./chunks/framework.Ai2o9gNv.js";const t="/assets/image-20250104194004233.DXkXfmHX.png",i="/assets/image-20250104191515226.Di8eDNjz.png",r="/assets/image-20250104194756416.D2CguRmI.png",A="/assets/0FB7BC5A.BdqdgnS3.png",p="/assets/image-20250104191602656.jRl3J9fr.png",o="/assets/image-20250104191831548.BBr5_IkG.png",g="/assets/0FB7BC5A.BdqdgnS3.png",m="/assets/image-20250104192327298.IBo2YPsA.png",B="/assets/image-20250104192519324.DAcga4jh.png",u=JSON.parse('{"title":"鸿蒙元服务实战-笑笑五子棋（1）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（1）/鸿蒙元服务实战-笑笑五子棋（1）.md","filePath":"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（1）/鸿蒙元服务实战-笑笑五子棋（1）.md","lastUpdated":1736065340000,"__rawMarkdown":"# 鸿蒙元服务实战-笑笑五子棋（1）\\n\\n## 前言\\n\\n作为鸿蒙应用的深度开发者都应该知道，经历了**波澜壮阔12月风波**，到2025年新的开始。鸿蒙应用开发的热度算是下去一些了。\\n\\n这里就把之前上架了的元服务-《笑笑五子棋》给开源分享出来。\\n\\n## 笑笑五子棋\\n\\n笑笑五子棋的名字比较朴素，因为**笑笑**这个名字是我女儿的名字，这也应该是众多屌丝程序员独有的浪漫了吧（自嗨）。\\n\\n界面风格如下：\\n\\n![image-20250104194004233](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104194004233.png)\\n\\n\\n\\n## 笑笑五子棋的数据\\n\\n当然，笑笑五子棋也是拿到了元服务的基础激励的。\\n\\n![image-20250104191515226](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104191515226.png)\\n\\n---\\n\\n目前是付款中状态：\\n\\n\\n\\n![image-20250104194756416](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104194756416.png)\\n\\n> 这个金额是假的！！![img](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/0FD04174.png)\\n\\n上架时间是 **2025-12-09**。\\n\\n![image-20250104191602656](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104191602656.png)\\n\\n基础激励的要求是 7天活跃设备100。也是达到了。\\n\\n![image-20250104191831548](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104191831548.png)\\n\\n这个日活**dddd** ![img](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/0FB7BC5A.png)\\n\\n然后比较开心的是最近这个应用还上了**鸿蒙负一屏的休闲分类菜单**中。\\n\\n![image-20250104192327298](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104192327298.png)\\n\\n\\n\\n出现比较靠前的位置后，活跃数据更加出众了。\\n\\n![image-20250104192519324](%E9%B8%BF%E8%92%99%E5%85%83%E6%9C%8D%E5%8A%A1%E5%AE%9E%E6%88%98-%E7%AC%91%E7%AC%91%E4%BA%94%E5%AD%90%E6%A3%8B%EF%BC%881%EF%BC%89.assets/image-20250104192519324.png)\\n\\n\\n\\n然后因为是个人开发者，所以在对接广告上存在困难。如果是用企业资质的话，引入广告还是很容易的。\\n\\n\\n\\n## 相关的技术\\n\\n主要用到了以下技术\\n\\n1. ArkTS API 12\\n2. Canvas\\n3. 元服务独有的AtomicServiceTabs\\n4. 卡片开发\\n5. 元服务的创建\\n6. 元服务的上架\\n\\n\\n\\n## 小结\\n\\n这篇文章主要是介绍了这个应用的周边，下一篇文章主要围绕代码技术开展。\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n\\n\\n"}'),l={name:"鸿蒙开发技巧/鸿蒙元服务实战-笑笑五子棋/鸿蒙元服务实战-笑笑五子棋（1）/鸿蒙元服务实战-笑笑五子棋（1）.md"};function _(C,n,c,d,h,F){return E(),s("div",null,[...n[0]||(n[0]=[e('<h1 id="鸿蒙元服务实战-笑笑五子棋-1" tabindex="-1">鸿蒙元服务实战-笑笑五子棋（1） <a class="header-anchor" href="#鸿蒙元服务实战-笑笑五子棋-1" aria-label="Permalink to &quot;鸿蒙元服务实战-笑笑五子棋（1）&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>作为鸿蒙应用的深度开发者都应该知道，经历了<strong>波澜壮阔12月风波</strong>，到2025年新的开始。鸿蒙应用开发的热度算是下去一些了。</p><p>这里就把之前上架了的元服务-《笑笑五子棋》给开源分享出来。</p><h2 id="笑笑五子棋" tabindex="-1">笑笑五子棋 <a class="header-anchor" href="#笑笑五子棋" aria-label="Permalink to &quot;笑笑五子棋&quot;">​</a></h2><p>笑笑五子棋的名字比较朴素，因为<strong>笑笑</strong>这个名字是我女儿的名字，这也应该是众多屌丝程序员独有的浪漫了吧（自嗨）。</p><p>界面风格如下：</p><p><img src="'+t+'" alt="image-20250104194004233"></p><h2 id="笑笑五子棋的数据" tabindex="-1">笑笑五子棋的数据 <a class="header-anchor" href="#笑笑五子棋的数据" aria-label="Permalink to &quot;笑笑五子棋的数据&quot;">​</a></h2><p>当然，笑笑五子棋也是拿到了元服务的基础激励的。</p><p><img src="'+i+'" alt="image-20250104191515226"></p><hr><p>目前是付款中状态：</p><p><img src="'+r+'" alt="image-20250104194756416"></p><blockquote><p>这个金额是假的！！<img src="'+A+'" alt="img"></p></blockquote><p>上架时间是 <strong>2025-12-09</strong>。</p><p><img src="'+p+'" alt="image-20250104191602656"></p><p>基础激励的要求是 7天活跃设备100。也是达到了。</p><p><img src="'+o+'" alt="image-20250104191831548"></p><p>这个日活<strong>dddd</strong> <img src="'+g+'" alt="img"></p><p>然后比较开心的是最近这个应用还上了<strong>鸿蒙负一屏的休闲分类菜单</strong>中。</p><p><img src="'+m+'" alt="image-20250104192327298"></p><p>出现比较靠前的位置后，活跃数据更加出众了。</p><p><img src="'+B+'" alt="image-20250104192519324"></p><p>然后因为是个人开发者，所以在对接广告上存在困难。如果是用企业资质的话，引入广告还是很容易的。</p><h2 id="相关的技术" tabindex="-1">相关的技术 <a class="header-anchor" href="#相关的技术" aria-label="Permalink to &quot;相关的技术&quot;">​</a></h2><p>主要用到了以下技术</p><ol><li>ArkTS API 12</li><li>Canvas</li><li>元服务独有的AtomicServiceTabs</li><li>卡片开发</li><li>元服务的创建</li><li>元服务的上架</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这篇文章主要是介绍了这个应用的周边，下一篇文章主要围绕代码技术开展。</p><p>如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。</p>',31)])])}const b=a(l,[["render",_]]);export{u as __pageData,b as default};
